import { useEffect, useReducer, useRef, useState } from 'react';
import { ApiError, forgetStory, startStory } from './api/client';
import { connectEvents, type Connection } from './api/events';
import type { Fixture } from './api/types';
import { DemoBadge } from './components/DemoBadge';
import { stop } from './lib/sound';
import { End } from './screens/End';
import { Grownups } from './screens/Grownups';
import { OrderGame, orderPages } from './screens/OrderGame';
import { Quiz, type QuizResult } from './screens/Quiz';
import { Draw } from './screens/Draw';
import { Making } from './screens/Making';
import { NameHero } from './screens/NameHero';
import { PickLesson } from './screens/PickLesson';
import { Reader } from './screens/Reader';
import { Refusal } from './screens/Refusal';
import { Welcome } from './screens/Welcome';
import { getSettings } from './state/settings';
import { releaseSource, type Screen, type Source } from './state/session';
import { initialStory, storyReducer } from './state/storyReducer';
import { Icon } from './components/Icon';

// The screen machine: welcome -> draw -> name -> lesson -> making -> reader -> end, plus refusal and the grown-ups area.
// Everything the child chose lives in memory only. The story itself is folded from the event stream by storyReducer.
export default function App() {
  const [screen, setScreen] = useState<Screen>('welcome');
  const [back, setBack] = useState<Screen>('welcome'); // where the grown-ups area returns to
  const [source, setSource] = useState<Source | null>(null);
  const [heroName, setHeroName] = useState('');
  const [lessonId, setLessonId] = useState<string | null>(null);
  const [lessonTitle, setLessonTitle] = useState<string | undefined>();
  const [promises, setPromises] = useState<string[]>([]);
  const [practice, setPractice] = useState<{ quiz: QuizResult[]; ordered: boolean }>({ quiz: [], ordered: false });
  const [storiesMade, setStoriesMade] = useState(0);
  const [starting, setStarting] = useState(false);
  const [startError, setStartError] = useState('');
  const [readFrom, setReadFrom] = useState(1);
  const [story, dispatch] = useReducer(storyReducer, initialStory);
  const conn = useRef<Connection | null>(null);
  const [online, setOnline] = useState(typeof navigator === 'undefined' ? true : navigator.onLine);

  useEffect(() => {
    const on = () => setOnline(true);
    const off = () => setOnline(false);
    window.addEventListener('online', on);
    window.addEventListener('offline', off);
    return () => { window.removeEventListener('online', on); window.removeEventListener('offline', off); };
  }, []);

  const closeStream = () => { conn.current?.close(); conn.current = null; };
  useEffect(() => closeStream, []);

  const go = (s: Screen) => { stop(); setScreen(s); window.scrollTo?.(0, 0); };
  const openGrownups = (from: Screen) => { setBack(from); go('grownups'); };

  const newStory = () => {
    closeStream();
    dispatch({ type: 'reset' });
    releaseSource(source);
    setSource(null);
    setHeroName('');
    setLessonId(null);
    setPromises([]);
    setPractice({ quiz: [], ordered: false });
    setStartError('');
    go('draw');
  };

  const begin = async () => {
    if (!source || !lessonId || starting) return;
    setStarting(true);
    setStartError('');
    try {
      const { storyId } = await startStory({
        lessonId, age: getSettings().age, heroName: heroName || undefined, pictures: getSettings().pictures, promises: promises.map((p) => p.trim()).filter(Boolean),
        drawing: source.kind === 'sample' ? { kind: 'fixture', id: source.id } : { kind: 'file', blob: source.blob, name: source.kind === 'photo' ? 'drawing.jpg' : 'drawing.png' },
      });
      closeStream();
      dispatch({ type: 'reset' });
      conn.current = connectEvents(storyId, { onEvent: (ev) => dispatch({ type: 'event', ev }), onNet: (net) => dispatch({ type: 'net', net }) });
      setReadFrom(1);
      go('making');
    } catch (e) {
      const busy = e instanceof ApiError && e.code === 'busy';
      setStartError(busy ? 'Pip is busy with other stories. Please try again in a minute.' : e instanceof ApiError && e.status === 0 ? 'No internet. Let’s try again!' : 'Oops, Pip dropped a page. Let’s try again!');
    } finally {
      setStarting(false);
    }
  };

  // A refusal arrives as a normal event: move to the calm screen. Never keep the child on the progress screen.
  useEffect(() => { if (story.phase === 'refused' && screen === 'making') go('refusal'); }, [story.phase, screen]);

  const useSample = (f: Fixture) => {
    closeStream();
    dispatch({ type: 'reset' });
    releaseSource(source);
    setSource({ kind: 'sample', id: f.id, url: f.url, label: f.label, fkind: f.kind });
    setLessonId(null);
    go('name');
  };

  // After the last page: a quiz about the story (if it passed its promises), then a picture-order game, then the end.
  const finishPlay = () => { setStoriesMade((n) => n + 1); go('end'); };
  const afterQuiz = () => (orderPages(story).length ? go('order') : finishPlay());
  // The quiz is made after the story is verified, so it may arrive after the child has read the last page: it is offered on the
  // end screen as a button that appears when it is ready, never forced.
  const afterReading = () => (story.quiz?.items.length ? go('quiz') : finishPlay());

  const forget = async () => {
    if (story.storyId) await forgetStory(story.storyId).catch(() => { /* the server may already have lost it */ });
    newStory();
    go('welcome');
  };

  let view;
  switch (screen) {
    case 'welcome':
      view = <Welcome onStart={() => go('draw')} onGrownups={() => openGrownups('welcome')} />;
      break;
    case 'draw':
      view = <Draw initial={source} onBack={() => go('welcome')} onDone={(s) => { if (source !== s) releaseSource(source); setSource(s); go('name'); }} />;
      break;
    case 'name':
      view = source ? <NameHero source={source} name={heroName} onRedraw={() => { releaseSource(source); setSource(null); go('draw'); }} onNext={(n) => { setHeroName(n); go('lesson'); }} /> : null;
      break;
    case 'lesson':
      view = <PickLesson chosen={lessonId} starting={starting} error={startError} promises={promises} onPromises={setPromises} onBack={() => go('name')} onPick={(l) => { setLessonId(l.id); setLessonTitle(l.title); }} onGo={begin} />;
      break;
    case 'making':
      view = <Making story={story} source={source} lessonTitle={lessonTitle} onCancel={newStory} onRetry={() => conn.current?.retry()} onRead={() => { setReadFrom(1); go('reader'); }} />;
      break;
    case 'reader':
      view = <Reader story={story} source={source} startAt={readFrom} onEnd={afterReading} onLeave={() => go('welcome')} />;
      break;
    case 'quiz':
      view = <Quiz story={story} onBack={afterQuiz} onDone={(r) => { setPractice((p) => ({ ...p, quiz: r })); afterQuiz(); }} />;
      break;
    case 'order':
      view = <OrderGame story={story} onBack={finishPlay} onDone={() => { setPractice((p) => ({ ...p, ordered: true })); finishPlay(); }} />;
      break;
    case 'end':
      view = <End story={story} lessonTitle={lessonTitle} restSuggested={storiesMade >= 2} canOrder={orderPages(story).length > 0} onQuiz={() => go('quiz')} onOrder={() => go('order')} onAgain={() => { setReadFrom(1); go('reader'); }} onNew={newStory} onGrownups={() => openGrownups('end')} />;
      break;
    case 'refusal':
      view = <Refusal story={story} onAgain={newStory} onGrownups={() => openGrownups('refusal')} />;
      break;
    case 'grownups':
      view = <Grownups story={story} practice={practice} onBack={() => go(back)} onUseSample={useSample} onForget={forget} />;
      break;
  }

  return (
    <div className="app" data-screen={screen}>
      {!online && (
        <div className="offline" role="status"><Icon name="cloud" /> No internet. Pip will keep trying.</div>
      )}
      {view}
      <DemoBadge />
    </div>
  );
}
// The drawing canvas. Pointer events only (finger, pen, mouse). Strokes are kept as data, so undo is unlimited and the picture is
// re-painted cleanly. Exported at 1024 px on the long edge on a white page (metadata-free PNG).
import { forwardRef, useCallback, useEffect, useImperativeHandle, useRef } from 'react';

export const W = 1024;
export const H = 768;

interface Stroke { color: string; size: number; pts: { x: number; y: number }[] }

export interface DrawHandle {
  undo(): void;
  clear(): void;
  hasInk(): boolean;
  toBlob(): Promise<Blob>;
}

interface Props {
  color: string;
  size: number; // brush width in canvas pixels
  onChange(strokes: number): void;
  label: string;
}

function paint(ctx: CanvasRenderingContext2D, s: Stroke, from = 0) {
  ctx.strokeStyle = s.color;
  ctx.fillStyle = s.color;
  ctx.lineWidth = s.size;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const p = s.pts;
  if (p.length === 1) {
    ctx.beginPath();
    ctx.arc(p[0].x, p[0].y, s.size / 2, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  ctx.beginPath();
  const start = Math.max(1, from);
  ctx.moveTo((p[start - 1].x + (p[start]?.x ?? p[start - 1].x)) / 2, (p[start - 1].y + (p[start]?.y ?? p[start - 1].y)) / 2);
  for (let i = start; i < p.length - 1; i++) {
    const mx = (p[i].x + p[i + 1].x) / 2;
    const my = (p[i].y + p[i + 1].y) / 2;
    ctx.quadraticCurveTo(p[i].x, p[i].y, mx, my);
  }
  ctx.lineTo(p[p.length - 1].x, p[p.length - 1].y);
  ctx.stroke();
}

export const DrawCanvas = forwardRef<DrawHandle, Props>(function DrawCanvas({ color, size, onChange, label }, ref) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const strokes = useRef<Stroke[]>([]);
  const live = useRef<{ id: number; s: Stroke; drawn: number } | null>(null);
  const penUntil = useRef(0);
  const props = useRef({ color, size });
  props.current = { color, size };

  const ctx = () => canvas.current!.getContext('2d')!;

  const redraw = useCallback(() => {
    const c = ctx();
    c.fillStyle = '#FFFFFF';
    c.fillRect(0, 0, W, H);
    strokes.current.forEach((s) => paint(c, s));
  }, []);

  useEffect(() => { redraw(); }, [redraw]);

  useImperativeHandle(ref, () => ({
    undo() { strokes.current.pop(); redraw(); onChange(strokes.current.length); },
    clear() { strokes.current = []; redraw(); onChange(0); },
    hasInk: () => strokes.current.length > 0,
    toBlob: () => new Promise<Blob>((resolve, reject) => canvas.current!.toBlob((b) => (b ? resolve(b) : reject(new Error('no image'))), 'image/png')),
  }), [onChange, redraw]);

  const at = (e: React.PointerEvent) => {
    const r = canvas.current!.getBoundingClientRect();
    return { x: ((e.clientX - r.left) * W) / r.width, y: ((e.clientY - r.top) * H) / r.height };
  };

  const down = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (live.current) return; // a second finger never starts a second stroke
    if (e.pointerType === 'pen') penUntil.current = Date.now() + 2000;
    // Palm rejection: ignore large contacts, and any touch just after the pen was used.
    if (e.pointerType === 'touch' && (Math.max(e.width, e.height) > 48 || Date.now() < penUntil.current)) return;
    if (e.button > 0) return;
    e.preventDefault();
    canvas.current!.setPointerCapture(e.pointerId);
    const s: Stroke = { color: props.current.color, size: props.current.size, pts: [at(e)] };
    live.current = { id: e.pointerId, s, drawn: 0 };
    paint(ctx(), s);
  };

  const move = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const l = live.current;
    if (!l || l.id !== e.pointerId) return;
    const events = e.nativeEvent.getCoalescedEvents?.() ?? [e.nativeEvent];
    const r = canvas.current!.getBoundingClientRect();
    for (const ev of events.length ? events : [e.nativeEvent]) {
      l.s.pts.push({ x: ((ev.clientX - r.left) * W) / r.width, y: ((ev.clientY - r.top) * H) / r.height });
    }
    if (l.s.pts.length > 2) { paint(ctx(), l.s, Math.max(1, l.s.pts.length - events.length - 1)); }
  };

  const up = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const l = live.current;
    if (!l || l.id !== e.pointerId) return;
    live.current = null;
    strokes.current.push(l.s);
    redraw(); // smooth, final version of the stroke
    onChange(strokes.current.length);
  };

  return (
    <canvas
      ref={canvas}
      className="draw-canvas"
      width={W}
      height={H}
      role="img"
      aria-label={label}
      onPointerDown={down}
      onPointerMove={move}
      onPointerUp={up}
      onPointerCancel={up}
    />
  );
});
import { useCallback, useEffect, useRef, useState } from 'react';
import { getFixtures } from '../api/client';
import type { Fixture } from '../api/types';
import { Btn } from '../components/Btn';
import { ConfirmPictures } from '../components/ConfirmPictures';
import { DrawCanvas, type DrawHandle } from '../components/DrawCanvas';
import { Icon } from '../components/Icon';
import { Pip } from '../components/Pip';
import { BRUSHES, CRAYONS, ERASER } from '../components/palette';
import { SoundToggle } from '../components/SoundToggle';
import { say, sfx } from '../lib/sound';
import { useFocusHeading, type Source } from '../state/session';

const MAX_SIDE = 1024;

/** A photo of a paper drawing, scaled down to 1024 px and re-encoded (which also drops any metadata). */
async function preparephoto(file: File): Promise<Blob> {
  const bmp = await createImageBitmap(file); // honours the photo's rotation
  const scale = Math.min(1, MAX_SIDE / Math.max(bmp.width, bmp.height));
  const c = document.createElement('canvas');
  c.width = Math.round(bmp.width * scale);
  c.height = Math.round(bmp.height * scale);
  const ctx = c.getContext('2d')!;
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, c.width, c.height);
  ctx.drawImage(bmp, 0, 0, c.width, c.height);
  return new Promise((res, rej) => c.toBlob((b) => (b ? res(b) : rej(new Error('encode'))), 'image/jpeg', 0.9));
}

// 6.2 Draw. Crayons, three brush sizes, undo, start over (asks with pictures), a photo of a paper drawing, and sample drawings.
export function Draw({ initial, onDone, onBack }: { initial: Source | null; onDone(s: Source): void; onBack(): void }) {
  const h = useFocusHeading<HTMLHeadingElement>();
  const pad = useRef<DrawHandle>(null);
  const [color, setColor] = useState<string>(CRAYONS[0].id);
  const [brush, setBrush] = useState<number>(1);
  const [ink, setInk] = useState(0);
  const [confirmClear, setConfirmClear] = useState(false);
  const [preview, setPreview] = useState<Source | null>(initial && initial.kind !== 'canvas' ? initial : null);
  const [samples, setSamples] = useState<Fixture[]>([]);
  const [hint, setHint] = useState('');
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let live = true;
    getFixtures().then((f) => { if (live) setSamples(f.filter((x) => x.kind === 'benign')); }).catch(() => { /* samples are a bonus: stay quiet */ });
    return () => { live = false; };
  }, []);

  const hex = color === ERASER.id ? ERASER.hex : CRAYONS.find((c) => c.id === color)!.hex;
  const onChange = useCallback((n: number) => { setInk(n); if (n) setHint(''); }, []);

  const finish = async () => {
    if (preview) { onDone(preview); return; }
    if (!pad.current?.hasInk()) { setHint('Draw your hero first!'); say('keep-drawing'); return; }
    setBusy(true);
    try {
      const blob = await pad.current.toBlob();
      onDone({ kind: 'canvas', blob, url: URL.createObjectURL(blob) });
    } catch {
      setHint('Hmm, Pip could not save that. Try once more!');
    } finally {
      setBusy(false);
    }
  };

  const pickPhoto = async (file: File | undefined) => {
    if (!file) return;
    if (!file.type.startsWith('image/') || file.size > 30 * 1024 * 1024) { setHint('Pip can only open a picture. Try another one!'); return; }
    try {
      const blob = await preparephoto(file);
      setPreview({ kind: 'photo', blob, url: URL.createObjectURL(blob) });
      setHint('');
    } catch {
      setHint('Hmm, Pip could not open that picture. Try another one!');
    }
  };

  const brushPx = BRUSHES[brush].px;

  return (
    <main className="screen draw">
      <header className="screen-head">
        <button type="button" className="corner-btn" onClick={onBack} aria-label="Back to the start"><Icon name="arrow-left" /></button>
        <div className="head-pip"><Pip pose="happy" /></div>
        <h1 ref={h} tabIndex={-1} className="say">Draw your hero!</h1>
        <SoundToggle />
      </header>

      <div className="draw-body">
        <div className="stage-col">
          <div className="sheet" data-preview={!!preview}>
            {preview ? <img className="sheet-img" src={preview.url} alt={preview.kind === 'sample' ? `Sample drawing: ${preview.label}` : 'Your picture'} /> : (
              <DrawCanvas ref={pad} color={hex} size={brushPx} onChange={onChange} label="Drawing page. Draw with a finger, a pen or a mouse." />
            )}
          </div>
          {!preview && (
            <div className="tray" role="group" aria-label="Crayons">
              {CRAYONS.map((c) => (
                <button key={c.id} type="button" className="crayon" aria-pressed={color === c.id} aria-label={c.name} data-color={c.id}
                  onClick={() => { setColor(c.id); sfx('select'); }}>
                  <img src={`/assets/crayons/${c.id}.webp`} alt="" draggable={false} />
                </button>
              ))}
              <button type="button" className="crayon crayon-eraser" aria-pressed={color === ERASER.id} aria-label="Eraser" onClick={() => { setColor(ERASER.id); sfx('select'); }}>
                <img src="/assets/ui/eraser.webp" alt="" draggable={false} />
              </button>
            </div>
          )}
        </div>

        <aside className="tools" aria-label="Drawing tools">
          {!preview ? (
            <>
              <div className="brushes" role="group" aria-label="Brush size">
                {BRUSHES.map((b, i) => (
                  <button key={b.id} type="button" className="brush" aria-pressed={brush === i} aria-label={b.name} onClick={() => { setBrush(i); sfx('select'); }}>
                    <i style={{ width: b.dot, height: b.dot }} />
                  </button>
                ))}
              </div>
              <div className="tool-row">
                <Btn variant="paper" round icon="arrow-counter-clockwise" aria-label="Undo" disabled={!ink} onClick={() => pad.current?.undo()} />
                <Btn variant="paper" round icon="trash" aria-label="Start over" disabled={!ink} onClick={() => setConfirmClear(true)} />
                <label className="btn btn-paper btn-round file-btn" aria-label="Use a photo of a paper drawing">
                  <Icon name="camera" />
                  <input type="file" accept="image/*" onChange={(e) => { pickPhoto(e.target.files?.[0]); e.target.value = ''; }} />
                </label>
              </div>
            </>
          ) : (
            <Btn variant="paper" icon="paint-brush" onClick={() => setPreview(null)}>Draw my own</Btn>
          )}
          <Btn big icon="star" onClick={finish} disabled={busy} aria-disabled={!preview && !ink} className={!preview && !ink ? 'is-soft' : ''}>Done!</Btn>
          <p className="hint" role="status" aria-live="polite">{hint}</p>
        </aside>

        {samples.length > 0 && (
          <section className="samples" aria-label="Sample drawings">
            <h2>Or try a sample drawing</h2>
            <ul>
              {samples.map((f) => (
                <li key={f.id}>
                  <button type="button" className="sample" aria-label={`Use the sample drawing: ${f.label}`}
                    data-selected={preview?.kind === 'sample' && preview.id === f.id}
                    onClick={() => { setPreview({ kind: 'sample', id: f.id, url: f.url, label: f.label, fkind: f.kind }); sfx('select'); }}>
                    <img src={f.url} alt="" loading="lazy" width={96} height={72} />
                  </button>
                </li>
              ))}
            </ul>
          </section>
        )}
      </div>

      {confirmClear && (
        <ConfirmPictures title="Start over?" yesLabel="Yes, start over" noLabel="Keep drawing" onNo={() => setConfirmClear(false)} onYes={() => { pad.current?.clear(); setConfirmClear(false); }} />
      )}
    </main>
  );
}

