        {children}
        <div className="confirm-actions">
          <Btn variant="sky" icon="arrow-left" onClick={onNo} data-autofocus>{noLabel}</Btn>
          <Btn variant="leaf" icon="check-circle" onClick={onYes}>{yesLabel}</Btn>
        </div>
      </div>
    </div>
  );
}
