  let i = 0;
  let stopped = false;
  const next = () => {
    if (stopped || i >= list.length) return;
    const ev = list[i];
    const prev = i === 0 ? 0 : list[i - 1].t;
    const wait = i === 0 ? 400 : Math.min(30_000, ((ev.t - prev) * 1000) / MOCK_SPEED);
    timer = setTimeout(() => {
      if (stopped) return;
      h.onEvent(ev);
      i++;
      next();
    }, wait);
  };
  next();
  return { close: () => { stopped = true; clearTimeout(timer); }, retry: () => {} };
}
