def judge_image(c: Commitment, image: bytes, mime: str, card_json: str) -> JudgeOut:
    """Image match needs eyes, which K2 does not have: Gemini vision reviews the real bytes. Honest limitation: the
    reviewer is the same family as the painter; the receipt records the model that judged."""
    model = get_settings().models.vision
    prompt = (
        f"{c.rubric}\n\nCHARACTER CARD (data): {card_json}\n"
        'Reply with JSON only: {"score": <0..1>, "reasoning": "<one short sentence>"}'
    )
    try:
        r = gemini.generate_json(prompt, images=[(image, mime)], model=model, temperature=0, max_tokens=300)
    except ClientError as e:
        return JudgeOut("verification_error", error=f"vision judge unavailable: {e}"[:200], model=model)
    v = r.value if isinstance(r.value, dict) else {}
    score = v.get("score")
    if not isinstance(score, int | float):
        return JudgeOut("verification_error", error="no score returned", model=model)
    status = "pass" if float(score) >= (c.pass_score or 0.8) else "violation"
    return JudgeOut(status, float(score), None, str(v.get("reasoning", ""))[:300], model=model,
                    tokens_in=r.usage.input_tokens, tokens_out=r.usage.output_tokens, latency_s=r.usage.latency_s)  # fmt: skip

    except Exception as e:  # pragma: no cover - depends on SDK/network
        log.warning("neatlogs init failed: %s", e)
    return _ready


def wrap(client: Any) -> Any:
    """Wrap a provider client so its calls become LLM spans (tokens, latency, cost)."""
    if not init():
        return client
    try:
        import neatlogs

        return neatlogs.wrap(client)
    except Exception as e:  # pragma: no cover
        log.warning("neatlogs.wrap failed: %s", e)
        return client


def span(kind: str = "TOOL", name: str | None = None, **kw: Any):
    """Decorator form of @neatlogs.span that is a no-op when tracing is off."""

    def deco(fn):
        if not init():
            return fn
        import neatlogs

        return neatlogs.span(kind=kind, name=name or fn.__name__, **kw)(fn)

    return deco


class _NullSpan:
    def set_attribute(self, *_a, **_k) -> None: ...


@contextlib.contextmanager
def guardrail_span(commitment: str, *, scope: str, input_text: str = "") -> Iterator[Any]:
    """One GUARDRAIL span per verdict. Set attributes through `record`."""
    if not init():
        yield _NullSpan()
        return
    import neatlogs

    with neatlogs.trace(f"verify:{commitment}", kind="GUARDRAIL") as s:
        s.set_attribute("neatlogs.guardrail.input", input_text[:4000])
        s.set_attribute("neatlogs.eval.commitment", commitment)
        s.set_attribute("neatlogs.eval.scope", scope)
        yield s


def record(span_obj: Any, verdict: dict) -> None:
    """Write a verdict (a plain dict) onto a guardrail span."""
    try:
        passed = verdict.get("status") in ("pass", "warning", "skipped")
        span_obj.set_attribute("neatlogs.guardrail.passed", passed)
        span_obj.set_attribute("neatlogs.guardrail.output", json.dumps(verdict, default=str)[:8000])
        if verdict.get("score") is not None:
            span_obj.set_attribute("neatlogs.guardrail.score", float(verdict["score"]))
        for k in ("status", "attempt", "verdict_by", "judge_model", "sampled"):
            if k in verdict and verdict[k] is not None:
                span_obj.set_attribute(f"neatlogs.eval.{k}", verdict[k])
    except Exception as e:  # pragma: no cover
        log.warning("record failed: %s", e)


def current_trace_id() -> str:
    """The active trace id (from the W3C traceparent neatlogs injects), or empty."""
