                                 "verdict": "pass" if all(v.ok for v in vs) else "warning"})  # fmt: skip

    def one_audio(p: Page) -> None:
        eng = run.engine
        data = None
        err = ""
        for attempt in range(2):
            try:
                data = tts.narrate(p.narration_text or f"{p.scenario} {p.question}").value
            except ClientError as e:
