  files[u] = name;
}
log(`${au.filter((e) => e.e === 'play').length} sounds played, ${Object.keys(files).length} files saved, ${au.filter((e) => e.e === 'rejected').length} rejected`);

await clickText('Settings', '[role="tab"]');
await sleep(1500);
