await sleep(2000);

await recorder.stop();
await browser.close();
fs.writeFileSync(path.join(OUT, 'cues.json'), JSON.stringify({ recStart, end: Date.now(), cues, audio: au, files, storyId, forgottenStatus: after, problems: [...new Set(problems)] }, null, 1));
console.log('\nPROBLEMS:', problems.length ? '\n  ' + [...new Set(problems)].join('\n  ') : 'none');
console.log(JSON.stringify({ storyId, forgottenStatus: after, heldBackPages: waited }));

